// Build Resend batch payloads from the audience the Trellis builder sent.
// Trellis posts the EXACT segment audience (already deduped + consent-filtered)
// plus an html_template with {{first_name}} / {{unsubscribe_url}} tokens.
// We personalize per recipient and chunk into arrays of <=100 for /emails/batch.
const input = $input.first().json;
const body = input.body || input;
const recipients = Array.isArray(body.recipients) ? body.recipients : [];
const subject = body.subject || '';
const template = body.html_template || body.html_body || '';
const from = body.from || 'ATL Urban Farms <sheree@atlurbanfarms.com>';
const campaignId = body.campaign_id || null;
const CHUNK = 100; // Resend /emails/batch hard limit is 100 messages per call

const personalize = (r) => {
  const email = r.email || '';
  const unsub = 'https://horvjqqifgrzxesuxtfm.supabase.co/functions/v1/unsubscribe?email=' + encodeURIComponent(email) + '&source=global';
  return template
    .replace(/\{\{\s*first_name\s*\}\}/g, r.first_name || 'Friend')
    .replace(/\{\{\s*email\s*\}\}/g, email)
    .replace(/\{\{\s*unsubscribe_url\s*\}\}/g, unsub);
};

// Drop rows without an email; if nothing is left, emit no items (no send).
const clean = recipients.filter(r => r && r.email);
if (clean.length === 0) return [];

const out = [];
for (let i = 0; i < clean.length; i += CHUNK) {
  const chunk = clean.slice(i, i + CHUNK);
  const batch = chunk.map(r => ({ from, to: [r.email], subject, html: personalize(r) }));
  out.push({ json: { batch, batch_index: out.length, count: chunk.length, campaign_id: campaignId } });
}
return out;

// Zips each Resend /emails/batch response with the recipients from the same
// chunk in "Build Resend Batches", so every sent message can be attributed to
// its campaign later. Resend's /emails/batch endpoint accepts no per-message
// tags/metadata, so this id-mapping table is how attribution rides along.
//
// PAIRING CHOICE: we use n8n's own pairedItem linkage via
// $('Build Resend Batches').itemMatching(i) instead of indexing
// $('Build Resend Batches').all()[batch_index]. "Resend Batch Dispatch" runs
// once per chunk item and n8n tracks a pairedItem link from each HTTP response
// item back to the exact input item that produced it -- itemMatching follows
// that tracked link, so it stays correct even if a request errors, retries, or
// items otherwise fail to preserve strict array order. Trusting batch_index /
// raw positional order would silently mis-pair recipients the moment that
// assumption breaks.
//
// Attribution must never break the send: any mismatch or exception for a chunk
// is skipped (that chunk's ids just won't be recorded) -- we never throw.
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  try {
    const source = $('Build Resend Batches').itemMatching(i).json;
    const response = items[i].json;
    const batch = Array.isArray(source.batch) ? source.batch : [];
    const campaignId = source.campaign_id || null;
    const subject = (batch.length && batch[0] && batch[0].subject) ? batch[0].subject : null;
    const ids = (response && Array.isArray(response.data)) ? response.data : null;

    // Shape mismatch (failed call, partial batch, etc.) -- skip this chunk only.
    if (!ids || ids.length !== batch.length) continue;

    for (let j = 0; j < ids.length; j++) {
      const id = ids[j] && ids[j].id;
      const to = (batch[j] && Array.isArray(batch[j].to)) ? batch[j].to[0] : null;
      if (!id || !to) continue;
      out.push({ json: { resend_email_id: id, campaign_id: campaignId, email: to, subject: subject } });
    }
  } catch (e) {
    continue; // no reliable pairing for this chunk -- skip, never throw
  }
}

return out;
